question.answer:
package main

import "fmt"

func force(knots int) int {
	switch {
	case knots < 1:
		return 0
	case knots < 11:
		return 3
	case knots < 28:
		return 6
	case knots < 48:
		return 9
	default:
		return 12
	}
}

func describe(level int) {
	switch level {
	case 0:
		fmt.Println("calm")
	case 3, 6:
		fmt.Println("breeze")
	case 9:
		fmt.Println("gale")
	case 12:
		fmt.Println("storm")
	default:
		fmt.Println("unknown")
	}
}

func advise(knots, licence int) {
	if f := force(knots); f <= licence {
		fmt.Println("sail at force", f)
	} else {
		fmt.Println("stay, force", f, "exceeds", licence)
	}
}

